// Helper functions
export function getPesticideById(id: string): Pesticide | undefined {
  return pesticides.find(p => p.id === id);
}

export function getPesticideBySlug(slug: string): Pesticide | undefined {
  return pesticides.find(p => p.slug === slug);
}

export function searchPesticides(query: string): Pesticide[] {
  const q = query.toLowerCase();
  return pesticides.filter(p => 
    p.name.toLowerCase().includes(q) ||
    p.activeIngredient.toLowerCase().includes(q) ||
    p.company.toLowerCase().includes(q) ||
    p.country.toLowerCase().includes(q)
  );
}

export function getPesticidesByCategory(category: string): Pesticide[] {
  return pesticides.filter(p => p.category === category);
}

export function getPesticidesByCountry(country: string): Pesticide[] {
  return pesticides.filter(p => p.country === country);
}

export function getCategories(): string[] {
  return [...new Set(pesticides.map(p => p.category))];
}

export function getCountries(): string[] {
  return [...new Set(pesticides.map(p => p.country))];
}

export function getActiveIngredients(): string[] {
  return [...new Set(pesticides.map(p => p.activeIngredient))];
}
